    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Määritä koko järjestelmän asetukset: perus-URL, suojaus, oletuskieli, aikavyöhyke, riskipisteytyksen oletusasetukset ja paljon muuta.',
    'SettingsPreferencesDesc'             => 'Oletusarvot ja toimintatapoihin liittyvät asetukset koko SimpleRiskissä: kieli, aikavyöhyke, auditoinnin tilat, riskikartoituksen vaatimukset, käyttöliittymän toiminnan kytkimet ja vastaavat.',
    'SettingsFileUploadDesc'              => 'Sallitut tiedostojen lähetystyypit ja eri liitetiedostokenttien kokorajoitukset.',
    'SettingsMailDesc'                    => 'Lähtevien sähköposti-ilmoitusten SMTP-määritykset, mukaan lukien siirto, isäntä, todennus ja vastausosoite.',
    'SettingsBackupsDesc'                 => 'Määritä varmuuskopioiden säilytys, aikataulu ja latauslinkit SimpleRisk-tietokannan varmuuskopioille.',
    'SettingsSecurityDesc'                => 'Todennuksen, istunnon, salasanakäytännön, perus-URL:n ja API:n tietoturva-asetukset.',
    'SettingsLoggingDesc'                 => 'Virheenkorjaus- ja tarkastuslokien määritys: lokitasot, säilytys ja lokitiedostojen sijainti.',
    'HealthCheckDesc'                     => 'Diagnosoi järjestelmän tila: PHP-versio, laajennukset, tiedostojen käyttöoikeudet, tietokantayhteys, cron-ajoitus ja Extra-lisäosien aktivoinnit.',
    'AnnouncementsDesc'                   => 'Luo ja hallinnoi kaikille käyttäjille näkyviä banneri-ilmoituksia.',
    'RegisterAndUpgradeDesc'              => 'Rekisteröi SimpleRisk-asennuksesi, anna tai uusi tilausavain ja käynnistä Core/Extra-päivitykset yhdellä napsautuksella.',
    'QueueMonitorDesc'                    => 'Tarkastele taustatöiden jonoa: odottavat, käynnissä olevat ja epäonnistuneet työt.',
    'ExtrasDesc'                          => 'Aktivoi, deaktivoi ja määritä SimpleRisk Extra -lisäosat (maksulliset laajennukset).',
    'ArtificialIntelligenceExtraDesc'     => 'Tekoäly Extra tarjoaa parannetun riskianalyysin (mukaan lukien FAIR-arvioinnit) ja räätälöidyn dokumentaation.',
    'CustomizationExtraDesc'              => 'Mukautuslisäominaisuus mahdollistaa erityyppisten kenttien lisäämisen ja poistamisen sekä mukautettujen sivupohjien dynaamisen luomisen.',
    'NotificationExtraDesc'               => 'Email Notification Extra mahdollistaa sen, että SimpleRisk lähettää sähköposti-ilmoituksia, kun riskejä lähetetään, muokataan tai niille tehdään muita toimia. Tämä Extra voidaan lisätä myös ajoitettuna komentosarjana, joka lähettää säännöllisiä muistutuksia, kun riskit ovat valmiita johdon katselmointiin. SimpleRisk Core -tuotteessa ilman tätä Extraa ilmoituksia ei välitetä työkalun ulkopuolelle.',
    'VulnerabilityManagementExtraDesc'    => 'Haavoittuvuuksien hallinnan lisäosa tarjoaa asiakkaille mahdollisuuden integroida SimpleRisk-instanssinsa Qualysiin, Tenable.io:hon tai Rapid7 Nexpose/InsightVM:ään ja tuoda sekä resurssi- että haavoittuvuustietoja SimpleRiskiin. Sieltä käsin voit valita, mitkä sivustot haluat käsitellä, määrittää, mitkä haavoittuvuuspisteet tuodaan, ja priorisoida, mitkä haavoittuvuudet muutetaan riskeiksi niiden seuraamiseksi.',
    'IncidentManagementExtraDesc'         => 'Incident Management Extra perustuu NIST 800-61 Computer Security Incident Handling Guide -oppaaseen ja tarjoaa poikkeamien hallinnan ominaisuudet SimpleRisk-järjestelmän sisällä.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Nimeä SimpleRiskin termistö (riski, omaisuuserä, viitekehys jne.) uudelleen koko käyttöliittymässä.',
    'RiskConfigurationDesc'               => 'Määritä riskin pisteytyssäännöt: tasot, riskinottohalukkuus, SLA-kynnysarvot sekä klassiset ja vaikuttaviin tekijöihin perustuvat riskikaavat.',
    'RiskAndThreatCatalogDesc'            => 'Ylläpidä alasvetovalikoissa käytettyjen riski- ja uhka-arvojen luetteloa.',
    'AddAndRemoveValuesDesc'              => 'Hallitse riskikenttien alasvetovalikkojen arvoja: sijainti, lähde, kategoria, tiimi, teknologia ja paljon muuta.',
    'AssetValuationDesc'                  => 'Määritä omaisuuserien arvostusasteikko ja omaisuuseräkohtaiset arvostuksen ohitukset.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Lisää, muokkaa, poista käytöstä ja nollaa käyttäjiä; hallitse salasanakäytäntöä.',
    'RoleManagementDesc'                  => 'Määrittele roolit ja kunkin roolin myöntämät käyttöoikeudet.',
    'TeamManagementDesc'                  => 'Luo ja hallinnoi tietueiden näkyvyyden suodatukseen käytettyjä tiimejä.',
    'SeparationExtraDesc'                 => 'Team-Based Separation Extra rajoittaa riskien katselun vain niihin käyttäjiin, jotka kuuluvat tiimiin, jolle riski on osoitettu. SimpleRisk Core -tuotteessa ilman tätä Extraa jokainen käyttäjä näkee jokaisen riskin.',
    'CustomAuthenticationExtraDesc'       => 'Mukautettu todennuslisäosa tukee Active Directory- ja SAML-todennusta. SimpleRisk Core -tuotteessa ainoa vaihtoehto ilman tätä lisäosaa on luoda uusia käyttäjiä SimpleRiskin identiteettitietovarastoon.',
    'EncryptionExtraDesc'                 => 'Encrypted Database Extra luo satunnaisen AES-256-bittisen salausavaimen ja käyttää sitä sitten arkaluonteisen tekstin salaamiseen ennen sen lisäämistä SimpleRisk-tietokantaan. Tämä estää ketään tarkastelemasta tai muokkaamasta tietoja käyttämättä suoraan SimpleRisk-sovellusta.',
    'OrganizationManagementDesc'          => "Organisaatiohierarkian lisäominaisuus mahdollistaa useiden liiketoimintayksiköiden määrittämisen, jotka voivat sisältää minkä tahansa määrän tiimejä. Käyttäjät voidaan sitten määrittää yhteen tai useampaan tiimiin eri liiketoimintayksiköiden alla. Tämä vaikuttaa käyttäjän kykyyn nähdä ja käyttää tiimejä, käyttäjiä ja resursseja, joihin he eivät ole liitettyjä.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Poista riskejä joukkotoimintona. Käytä säästeliäästi – poistot ovat pysyviä.',
    'AuditTrailDesc'                      => 'Hae ja vie järjestelmän auditointiloki käyttäjien toiminnoista.',
    'ImportExportExtraDesc'               => 'Import-Export Extra mahdollistaa tietojen tuonnin SimpleRiskiin kartoittamalla CSV-tiedoston kentät SimpleRiskin tietokannan kenttiin. Sillä voi tuoda auditoinnin tuloksia kolmannen osapuolen taulukkolaskennasta, haavoittuvuusskannauksen tuloksia toisesta työkalusta, omaisuuseriä CMDB:stä ja paljon muuta. Extra mahdollistaa myös CSV-tiedostojen viennin SimpleRiskistä, ja ne voivat sisältää riskejä, lieventämistoimia, katselmointeja tai yhdistelmäraportin kaikista kolmesta.',
    'JiraExtraDesc'                       => 'Jira Integration Extra antaa käyttäjille mahdollisuuden integroida kaksisuuntaisesti Jira-instanssin kanssa. Sen avulla riskit voidaan yhdistää Jira-tikettien kanssa ja synkronoida niiden tiedot, tila ja kommentit.',
    'APIExtraDesc'                        => 'API Extra antaa asiakkaille mahdollisuuden käyttää RESTful API:a komentosarjoitettujen vuorovaikutusten luomiseen muiden sovellusten kanssa, jotta saavutetaan edistynyt automaatio ja hyödynnetään olemassa olevaa infrastruktuuria.',
    'AdvancedSearchExtraDesc'             => 'Advanced Search Extra muuttaa yläpalkin hakukentän yhdeksi hauksi, joka kattaa riskit, viitekehykset, kontrollit, asiakirjat, poikkeukset, testit, auditoinnit, omaisuuserät ja omaisuuseräryhmät, ja tulosten läpikäyntiin on käytettävissä täysi Haku-sivu. Se näyttää vain ne tietueet, jotka käyttäjällä on lupa nähdä.',
    'AssessmentsExtraDesc'                => 'Risk Assessment Extra antaa käyttäjille mahdollisuuden määrittää yhteyshenkilöitä, luoda kysymyksiä (logiikka mukaan lukien), koota useita kysymyksiä kyselylomakemallilla, luoda kyselylomakkeita ja lähettää niitä yhteyshenkilöille, katsella kyselylomakkeen tuloksia, lisätä riskejä näiden tulosten perusteella, vertailla tuloksia ajan mittaan, tuoda ja viedä ulkoisesti mukautettuja arviointeja sekä tarkastella riskien arvioinnin auditointijälkeä.',
    'ActiveAssessmentsDesc'               => 'Tarkastele ja hallitse tällä hetkellä käynnissä olevia arviointeja.',
    'WorkflowsExtraDesc'                  => 'Workflows Extra tarjoaa visuaalisen, tapahtumaohjatun työnkulkumoottorin, joka automatisoi riskienhallinnan toimintoja SimpleRiskin tapahtumien perusteella. Voit suunnitella työnkulkuja, jotka käynnistyvät muutoksista — kuten riskin lähettämisestä, päivittämisestä tai katselmoinnista — jotta hyväksynnät ohjautuvat, työt osoitetaan ja prosessi etenee ilman manuaalista väliintuloa.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => "Secure Controls Framework (SCF) Extra on suora integraatio Secure Controls Frameworkin ja SimpleRiskin välillä. Se tuo SCF:n kontrolliluettelon ja niiden vastaavuuksien määritykset useissa eri vaatimustenmukaisuus- ja kyberturvallisuuskehyksissä SimpleRiskin hallintotoimintoihin, jotta voit ottaa käyttöön tarvitsemasi kehykset ja hallita niiden kontrolleja rakentamatta niitä käsin.",

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Siirrä vanhat varchar-tarkastelupäivämääräsarakkeet oikeisiin päivämäärätyyppeihin. Näkyvissä vain tarvittaessa.',
    'DatabaseUpgradeDesc'                 => 'Käynnistä SimpleRisk-tietokannan päivitysrutiini manuaalisesti.',

