    // someone who cannot take it.
    'HowDoYouWantToAddAFramework' => 'Miten haluat lisätä viitekehyksen?',
    'CreateFrameworkManually' => 'Luo manuaalisesti',
    'CreateFrameworkManuallyHint' => 'Anna viitekehykselle nimi itse ja lisää sitten sen kontrollit tai yhdistä ne.',
    // Named for the framework rather than for its vendor. The hint was reworded
