    'GetFrameworkFromScf' => 'Hae Secure Controls Framework -viitekehyksestä',
    'GetFrameworkFromScfHint' => 'Valitse julkaistu viitekehys ja lataa sen yhdistetyt kontrollit yhdessä vaiheessa.',
    'ImportFrameworkFromCatalog' => 'Tuo yksi',
    'ImportFrameworkFromCatalogHint' => 'Asenna viitekehys ja sen kontrollit SimpleRisk-sisältöluettelosta.',

    // The framework acquisition chooser's third route, which now offers the
