    'LayoutEditorHint' => 'Vedä kenttä toiseen korttiin määrittääksesi sen uudelleen, vedä kortin sisällä muuttaaksesi sen järjestystä tai kokoa ja vedä tai muuta kortin kokoa muuttaaksesi sen sijaintia sivulla.',
