    'AssetScoring' => 'Omaisuuserien pisteytys',
    'AssetScoringSettingsHint' => 'Jokainen omaisuuserä arvioidaan tasoille Matala, Kohtalainen tai Korkea luottamuksellisuuden, eheyden ja saatavuuden osalta, ja luottamuksellisuus voi sen sijaan olla Ei sovellettava, jolloin se jätetään pois molemmista tuloksista. Sen FIPS-luokitus on kolmesta arviosta korkein. Sen painotettu pistemäärä on kolmen tasoarvon painotettu keskiarvo, ja pistealueiden raja-arvot muuntavat tämän pistemäärän alueeksi Matala, Kohtalainen tai Korkea. Näiden asetusten muuttaminen pisteyttää kaikki omaisuuserät välittömästi uudelleen.',
    'Weights' => 'Painot',
