    'BandThresholds' => 'Pistealueiden raja-arvot',
    'AssetScoringBandThresholdsHint' => 'Painotettu pistemäärä, joka on raja-arvon tasolla tai sen yläpuolella, kuuluu kyseiseen pistealueeseen, ja Kohtalaisen raja-arvon alittava pistemäärä on Matala. Kohtalaisen on alettava Matalan arvon yläpuolelta, ja Korkean on alettava Kohtalaisen yläpuolelta eikä se voi olla Korkean arvoa suurempi.',
    'ModerateStartsAt' => 'Kohtalainen alkaa arvosta',
